MR.people["tang:p003"] = {
 "headline": "元舅辅政三十年，栽在一桩小案上",
 "lead": "长孙无忌字辅机，河南洛阳人，出自北魏皇族拓跋氏，父长孙晟是隋右骁卫将军，舅父高士廉；妹妹就是李世民的文德皇后。他少年与李世民交好，晋阳起兵后投效幕府，随军征讨，成为秦王府的核心谋臣。武德九年玄武门之变，他与房玄龄、杜如晦、尉迟敬德共同定策，助李世民夺位，事成之后封齐国公。贞观朝他历任吏部尚书、尚书右仆射、司空，贞观十七年力排众议拥立晋王李治为太子，又受命辅政。永徽年间他以元舅之尊独揽朝纲，借房遗爱案清除宗室与异己，宰相班子几乎尽出其门；永徽六年又迎合武昭仪，促成废王立武。显庆四年，许敬宗承武后之意诬其谋反，他被削爵流放黔州，途中被迫自缢，年六十三。直到上元年间才被追复官爵，其子长孙冲等亦受牵连流放。他的权柄全系在元舅二字上，皇帝一旦不需要这层亲，权也就跟着没了。",
 "points": [
  "转折一：秦王府谋臣出身，玄武门定策有功，封齐国公，是李世民最信得过的内亲兼谋主。",
  "转折二：贞观十七年力挺晋王李治为太子并受遗辅政，永徽年间以元舅之尊独揽朝纲，宰相多出其门。",
  "转折三：显庆四年被许敬宗诬以谋反，削爵流放黔州，途中自缢，上元年间方追复官爵。"
 ],
 "why": [
  {
   "q": "为什么长孙无忌能在高宗初年独揽朝纲？",
   "a": "因为他的身份把两重资格叠在了一处：既是拥立李治的定策人，又是皇帝的亲舅。高宗即位时年轻，朝中老臣多是贞观旧人，唯有他既通贞观旧政，又能以母族之亲直入内廷。他又极会用这个位置：房遗爱案一发，借谋反之名把宗室与不附己者一并清掉；宰相班子换过一茬，除李勣之外多是唯他马首是瞻的人。权力不是他抢来的，是制度与亲缘一起递到他手上的。",
   "basis": {
    "type": "book",
    "text": "《大唐兴亡三百年》第五章 永徽政局：长孙无忌的网"
   }
  },
  {
   "q": "为什么他最后会被一桩小案扳倒？",
   "a": "因为他的权柄没有自己的根。他的位置来自元舅二字，皇帝要用他时，这层亲是护身符；皇帝不需要他时，这层亲就是压在主上头上的影子。武昭仪要立后，旧相挡路，案子就从韦季方这样一个小人物身上起，许敬宗连夜突审，一句供词牵成谋反大狱。满朝多是他的人，此刻却没有人敢替他说话，因为替他说话就等于把自己也写进那张名单。",
   "basis": {
    "type": "book",
    "text": "《大唐兴亡三百年》长孙无忌的悲剧：不懂得及时放手"
   }
  }
 ],
 "gap": [
  "长孙无忌确切的出生月日，底本未载",
  "他在黔州自缢的具体情形，史无明文",
  "其子长孙冲流放后的结局，书中未载"
 ],
 "quotes": []
};
