    "a": "因为李治对他更有用。李泰有才名、有党羽，房遗爱就是众所周知的魏王心腹；李泰若即位，新朝的班底是魏王党，他这个舅父能保住尊位，却未必能保住相权。李治年幼仁厚，即位后须人辅政，元舅既亲且老，天然是那个辅政的人。底本只把疑问摆出来，没有替他明说；但从他后来的行事看，他选的是一个能让自己继续掌权的主子。",
