    "近端触发：永徽年间房遗爱谋反案发；房遗爱是众所周知的魏王李泰心腹，牵连宗室多人。",
    "决策者动机：他要借案清掉拥立晋王时未曾站在他这边的人，也要让宗室里敢说话的人闭嘴；房遗爱既是魏王党，又牵连宗室，是最好的由头。"
