    "a": "因为他手里的兵是安禄山交给他守河北的本钱，赔不起。史思明长于野战，李光弼长于守城与调度，硬拼一次已经折了锐气；九门城坚，退守可以等唐军粮尽。李光弼兵少，也不敢强攻，两边就这样耗着。他真正的转机不在九门城下，而在河北其他州县：只要把唐军的据点一个个拔掉，李光弼再能守也守不住一块飞地。缩在城里不是怯，是换了一种打法。",
