 "headline": "瓦岗旧将做到司空，死后却被剖棺",
 "lead": "李勣本姓徐，名世勣，字懋功，曹州离狐人，后徙滑州卫南。家中富有，多僮仆，他十七岁随翟让在瓦岗起兵，劝翟让截取运河商旅以充军资，瓦岗由此从饥民聚众变成一支能养兵的军。李密据瓦岗时他任右武候大将军；武德元年李密降唐，他不肯拿主公的旧地自献邀功，只把黎阳仓的户口册籍交出去，高祖赐姓李，后来又避李世民讳，去世字单名勣。秦王与太子刀兵相见那年，他按兵观望，不预其事。贞观朝他任并州都督、兵部尚书，贞观十七年图形凌烟阁，李治被立为太子后又被任为太子詹事。永徽年间废王立武之争，满朝争得不可开交，他始终不开口。乾封元年他以七十三岁高龄挂帅东征，总章元年攻灭高丽，完成太宗未竟之业。总章二年卒，年七十六，谥贞武，陪葬昭陵；其孙徐敬业后来起兵反武，兵败后被剖棺戮尸，李氏一门亦遭牵连。",
 "points": [
  "转折一：曹州富家子十七岁上瓦岗，劝翟让截运河商旅充军资，归唐时不肯以主公旧地自献，反得高祖赐姓。",
  "转折二：贞观朝任并州都督、兵部尚书，图形凌烟阁，又做过李治的太子詹事；废王立武之争中始终不开口。",
  "转折三：七十三岁挂帅东征，总章元年攻灭高丽；死后其孙徐敬业反武，他被剖棺戮尸。"
 ],
 "why": [
  {
   "q": "为什么李勣历三朝而不倒，最后还成了灭高丽的挂帅之人？",
   "a": "因为他一辈子只做两件事：打仗与不表态。瓦岗出身使他不是关陇贵戚的门客，归唐时不肯自献旧地，让高祖看见他的忠；玄武门之变他不预其事，废王立武他不开口，两次大险都躲在门外的位置。皇帝用他，正因为他不结党、不抢功、交代得下去的军务一定办成。贞观朝让他做并州都督、兵部尚书，又让他做李治的太子詹事，是把这个无害而有用的老将放进储君身边。到了东征高丽，满朝开国名将只剩他一人，挂帅的也就只能是他。",
   "basis": {
    "type": "book",
    "text": "《大唐兴亡三百年》平定高丽：李勣老而弥坚（上）"
   }
  }
 ],
