   "a": "因为隋末的河北需要一个能维持秩序的人，而他恰好是那种人。征高丽的徭役把丁壮逼得四处逃亡，州县的控制一松，谁能让百姓活下去，谁就是那里的主。窦建德起兵之后不杀不掠，降官降将多能保全，这一条在乱世里比什么都值钱。他又肯把州县的钱粮、刑名接过来办，境内安生，商贾肯做生意，人心就一点点归了他。出身低不低，河北的百姓并不看重，他们看重的是明年还能不能种地。",
