   "a": "因为他活着，河北的人心就还有一个去处。唐廷在河北的官是打进去的，州县认的却是夏朝那六年；一个被俘的夏王哪怕关在长安，旧部也会觉得还有指望。他待降将宽厚，赦过李盖，也礼遇过李神通，这些事在河北传得很广，比几座城更难对付。杀他，是要把那个念想斩断。",
