    "a": "因为弹章只是最后一击，缺口是他自己留的。封禅一场大典，扈从滥赏、费用浩繁，朝中早有怨言；他在相位日久，用人多出私意，得罪的人不止一个。宇文融正在替朝廷清查逃户，手里有账、有吏、有御前的宠信，要立威就得挑一个够分量的人。玄宗也愿意用新锐换掉旧臣。他自己身上没有纰漏，别人再使劲也送不进监狱；有了纰漏，一夜间就能进去。",
