MR.people["tang:p019"] = {
 "headline": "替朝廷打到底，最后被逼成叛臣",
 "lead": "仆固怀恩是铁勒仆骨部人，家世袭金微都督，是朔方军里最能打的一路蕃将。安史之乱起，他追随郭子仪东征西讨，朔方军倚为柱石；至德二载随广平王李俶收复两京，以功封丰国公。他性情刚决，敢犯上，麾下的蕃汉劲卒仗着军功多为不法，长期受他包庇，朝廷要用他，弹章一次次按下不问。乾元二年邙山一战，他不听调令先退，致李光弼大败，因此被免官。宝应元年他率部紧追史朝义，收复洛阳，其子仆固玚又击溃燕军；他的女儿由肃宗做主嫁给回纥，后来成了回纥的王后。广德元年，他送回纥出塞途经太原，河东节度辛云京闭城不纳，宦官骆奉先又告他谋反；他上表自讼不获申，怕入朝即死，索性举兵，引回纥、吐蕃南下。永泰元年，他暴卒于鸣沙，年约五十，联军顿时失去纽带，其部众数易其主，郭子仪单骑入回纥营，关中之危才解。谥号底本无载。",
 "points": [
  "转折一：以铁勒蕃将之子从郭子仪征战，至德二载收两京封丰国公，成为朔方军柱石，也纵容部众多为不法。",
  "转折二：乾元二年邙山违令先退致李光弼大败被免官；宝应元年追歼史朝义收复洛阳，又嫁女回纥结亲。",
  "转折三：广德元年受辛云京闭门之辱与骆奉先诬告，上表自讼不获申，举兵反唐，永泰元年暴卒鸣沙。"
 ],
 "why": [
  {
   "q": "为什么一个蕃将会成为朔方军的柱石？",
   "a": "因为安史之乱把唐廷能用的兵打光了。边军内调，府兵早已名存实亡，朔方军是朝廷手里最完整的一支劲旅；蕃将熟骑战、能节制部落，又不像汉将那样有朝中门生故吏，用起来既得力又放心。仆固怀恩世袭金微都督，本部人马跟着他走，收两京、追叛军都在最前面。爵位一封再封，兵却越交越多，朝廷离不开他，他也越来越离不开兵。",
   "basis": {
    "type": "book",
    "text": "《大唐兴亡三百年》临危受命：郭子仪和李光弼"
   }
  },
  {
   "q": "为什么功最高的蕃将最后被逼反？",
   "a": "因为朝廷给不了他要的东西，只给得起疑心。他功高而部下不法，朝中早有议论；送回纥出塞时辛云京闭城不纳，宦官骆奉先回朝就告他谋反。他上表自讼，朝廷不肯替他分辨，只劝他入朝；而入朝意味着交出兵权、听人审问，前头几个被杀的将帅就是榜样。反是死中求生，不反是束手待毙。他引回纥、吐蕃南下，要的其实是逼朝廷给一个清白，可兵一动，清白就再也要不回来了。",
   "basis": {
    "type": "book",
    "text": "《大唐兴亡三百年》烽火再燃：仆固怀恩之乱"
   }
  }
 ],
 "gap": [
  "他的生年，底本未载",
  "他世袭金微都督的承袭经过，史无明文",
  "骆奉先上奏的原文，书中未引",
  "他暴卒的原因，史无明文"
 ],
 "quotes": []
};
