MR.people["tang:p020"] = {
 "headline": "翻过葱岭的名将，死在潼关军帐",
 "lead": "高仙芝是高丽人，父亲高舍鸡在安西从军，他少年随父到安西，以父荫补游击将军，此后累迁安西副都护、四镇节度使。他身材魁伟，善骑射，出塞作战极勇，天宝六载率军远征小勃律，翻越葱岭，奇袭连云堡，唐的声威一时直抵葱岭以南。可他也贪，天宝九载破石国，掠其财宝、杀其丁壮，入朝献俘而授开府仪同三司；石国王子逃出控诉，中亚诸国因此结成反唐战线，并向黑衣大食求援。天宝十载怛罗斯一战，唐军因葛逻禄部临阵倒戈而大败，此后唐的势力退出中亚。安史之乱起，他任右金吾大将军，与封常清守陕郡，兵败退保潼关；监军边令诚入奏说他克扣军粮、弃地而走，天宝十五载他与封常清同被斩于潼关，年约六十，谥号书中未载。一个能翻葱岭的人，最后死在关中的一间军帐里。",
 "points": [
  "转折一：以父荫补游击将军，累迁安西副都护，成为安西四镇的重要将领。",
  "转折二：天宝六载远征小勃律、奇袭连云堡，威震中亚；天宝九载破石国献俘，却因屠城劫掠使诸国离心。",
  "转折三：怛罗斯因葛逻禄倒戈大败，唐退出中亚；安史乱起守陕郡退潼关，被监军边令诚诬告，与封常清同斩。"
 ],
 "why": [
  {
   "q": "为什么一个高丽军将之子能做到安西四镇节度使？",
   "a": "因为安西是一条只看军功的路。四镇孤悬西域，兵源靠当地蕃汉、内地募兵与罪犯拼成，能在那里立住的人靠的是骑射、识路、敢出塞，门第排不上用场。高仙芝长在军营与边市之间，父荫给了他一小块起步的官身，剩下全是打出来的。天宝年间唐与吐蕃在西域争道，朝廷要的就是敢翻葱岭、敢打远仗的将领，他正合这一路。军功一叠，节度使的印就交到他手上。",
   "basis": {
    "type": "book",
    "text": "《大唐兴亡三百年》封常清：我很丑，可是我很努力"
   }
  },
  {
   "q": "为什么屡立大功的名将最后被斩于潼关？",
   "a": "因为他手里没有能替自己说话的人。安禄山起兵后，唐廷仓促募兵，陕郡、潼关的守军多是新卒，退守是当时唯一可行的选择；可退守要有人担责。监军边令诚掌着直达御前的奏事之权，一纸入奏说他克扣军粮、弃地数百里，玄宗正在为败局找替罪的人，敕书一下，军中呼冤也救不回。他当年被夫蒙灵詧打压时，正是这个边令诚替他说过话；这一次，同一张嘴要了他的命。",
   "basis": {
    "type": "book",
    "text": "《大唐兴亡三百年》名将之死：为帝国的不幸买单"
   }
  }
 ],
 "gap": [
  "他的生年，底本未载",
  "越葱岭的具体日程，书中未全载",
  "怛罗斯参战各方的兵力，史无明文",
  "边令诚奏疏的原文，底本未引"
 ],
 "quotes": []
};
