MR.people["tang:p021"] = {
 "headline": "三度拜相，两度罢黜的救时宰相",
 "lead": "姚崇本名元崇，字元之，陕州硖石人，父亲姚懿官至嶲州都督。他早年以制举入仕，授濮州司仓参军，因才干出众累迁夏官郎中，管的是武选与兵籍这类琐碎账目。圣历元年他受武则天赏识，擢夏官侍郎、同凤阁鸾台平章事，第一次入相。神龙元年他参预诛杀张易之、张昌宗的密谋，助中宗复位，却因事成之后为废帝武曌落泪，招来同僚不满，外放为地方刺史。景云元年睿宗召他回朝复相，他与宋璟一同罢斜封官、整顿吏治，触动了大批靠侥幸得官的人，次年被太平公主排挤出朝，贬为同州刺史。先天二年玄宗在新丰驿召见他，他提出十事要说，随即拜兵部尚书、同中书门下三品，成为开元初年的主政宰相。开元四年因两个儿子受贿、亲信贪赃被揭发，他引咎罢相；开元八年以开府仪同三司致仕，开元九年卒，年七十二，谥文献。",
 "points": [
  "转折一：以制举入仕，从濮州司仓参军累迁夏官郎中，圣历元年受武则天赏识，第一次入相。",
  "转折二：神龙元年预诛二张助中宗复位，却因替废帝武曌落泪遭同僚不满，外放为刺史。",
  "转折三：景云复相与宋璟罢斜封官，被太平公主排挤出朝；先天二年献十事要说而复相，终因二子受贿罢相。"
 ],
 "why": [
  {
   "q": "为什么姚崇能三度入相，又每次都在权斗里被推出去？",
   "a": "因为他手里的本钱是实务与文笔，不是门第，也不是兵权。武周至开元初，宰相班子换得极勤，天子需要一个能把钱粮、武选、吏治这些具体账目理清的人，而这样的人朝中并不多。他每次入相，都赶上新君要立规矩的时候；每次被贬，都赶上旧势力反扑的时候。他没有自己的党羽，也没有一镇之兵，所以能被反复起用而不被当成威胁；也正因为没有根基，一旦触动既得利益，第一个被推出去顶账的就是他。三起三落，看着像反复无常，其实是他这种人的常态。",
   "basis": {
    "type": "book",
    "text": "《大唐兴亡三百年》姚崇：为盛世奠基（上）"
   }
  },
  {
   "q": "为什么玄宗即位之初，非要把他从同州贬所召回来？",
   "a": "因为玄宗刚刚在骊山阅兵立威，朝中张说一派把持着文柄，新君要立自己的班子，必须找一个不属于任何一派、又能立刻办事的老臣。姚崇做过两朝的宰相，又在同州当过刺史，实务没有生疏，名分上也没有短处。张说一听说他要回朝，立刻授意御史赵彦昭弹劾，正说明这个位置有多要紧。玄宗要的是听话又能干的人，姚崇要的是一个肯把条件讲在明处的君主，两边各取所需，才有新丰驿那一场问答。",
   "basis": {
    "type": "book",
    "text": "《大唐兴亡三百年》第八章 走向开元盛世"
   }
  }
 ],
 "gap": [
  "姚崇应制举的具体年份与科目，底本未载",
  "他外放亳州、宋州等地的任期先后，史无明文",
  "十事要说的逐条原文，书中未录全"
 ],
 "quotes": []
};
