    "a": "因为杀他不值，留他有用。李靖告变的时候，李渊还没有起兵的把握，最怕的是消息走漏到江都；事已至此，把这个知道内情的人公开处死，只会让更多人议论。李靖临刑那几句话把话说得体面，既认了李渊起兵的名分，又把自己摆在壮士的位置上。李世民再从旁求情，李渊就有了台阶。更重要的是，唐军正要东下平萧铣，缺的正是这种懂兵势、敢出奇的人。留着，是给自己添一副刀。",
