   "a": "因为他把自抑做成了习惯，儿孙却没有这份自觉。加封太子少师那天，东宫仪仗齐备，他却深自卑损，不敢修谒，直接回了家；天子面前，他从不把功劳说成自己的。这样的人，君主用着放心，也就没有下手的理由。可房家的门第与婚事都在最高处，房遗爱娶了高阳公主，早已卷进宗室夺嫡的圈子。父辈的谨慎传不下去，家门之祸就从下一代来了。",
