MR.people["tang:p028"] = {
 "headline": "齐王元吉，死在玄武门的第四子",
 "lead": "李元吉是唐高祖李渊的第四子，母亲窦氏，与长兄李建成、次兄李世民同母所生。他生得骁勇，骑射都在人上，性情却残暴寡恩，府中拿活人试刀，奶娘陈善意看不过去劝了几句，反被他借酒发作，命人活活打死。大业十三年父亲在晋阳举兵，他随大军入关；武德元年李渊称帝，封他为齐王，授并州总管。在并州任上他耽于游猎，不恤军民，武德二年刘武周南下，他弃太原逃回长安，因此被罢官。此后他转而依附太子李建成，成了东宫集团的主将，武德七年曾在内室埋伏刺客，打算刺杀李世民，事到临头被太子拦住。武德九年六月玄武门之变，他与李建成一同入朝，被尉迟敬德率领的骑兵追杀，年二十四，谥剌；五个儿子都被诛，贞观年间追封海陵郡王，仍谥剌。",
 "points": [
  "转折一：晋阳起兵时随军入关，武德元年封齐王、授并州总管，是李渊诸子中最早独当一面的一个。",
  "转折二：在并州耽于游猎、性残好杀，武德二年刘武周南下时弃太原逃回长安，因此被罢官，转而依附太子。",
  "转折三：成为东宫主将后两度谋刺李世民，武德九年玄武门之变中与李建成同被追杀，年二十四。"
 ],
 "why": [
  {
   "q": "为什么李元吉在并州任上会被罢官？",
   "a": "因为他把一方重镇当成了猎场。并州是李唐的龙兴之地，北面就是刘武周的锋芒，总管要管的是城墙、粮储与军情。他在任上整日出游打猎，军民政事都搁在一边，府里还拿活人试刀取乐，连奶娘的劝谏都被他用酒后的脾气打死。武德二年刘武周南下，他守不住，弃了太原一路逃回长安。丢的是自己的封地，也是朝廷北面的门户，罢官已经是最轻的处置。",
   "basis": {
    "type": "book",
    "text": "《大唐兴亡三百年》李元吉丢掉了太原"
   }
  },
  {
   "q": "为什么李元吉会站到太子一边，与亲兄李世民为敌？",
   "a": "因为他算的不是兄弟情分，是自己的位次。他心里清楚，李世民战功最盛、威望最高，一旦夺嫡成功，他这个第四子永远没有出头的日子；而与太子联手，先除掉秦王，回头再除掉太子，在他看来并不难。他在东宫与秦王府之间选了前者，还主动替太子动手，武德七年就在内室埋伏过刺客，武德九年又卷进下毒的事。他投的不是哪一个人，是自己还能往上走的那一线可能。",
   "basis": {
    "type": "book",
    "text": "《大唐兴亡三百年》看似天下太平"
   }
  }
 ],
 "gap": [
  "李元吉生于何月何日，底本未载",
  "他在并州任上的属官名单，史无明文",
  "齐王府卫士的员额与编制，书中未载"
 ],
 "quotes": []
};
