    "a": "因为他把自己绑在了太子的车上，而车是往宫门里走的。他失了并州之后没有自己的兵，能倚仗的只有东宫的名分与齐王府的几十个侍卫；他两次谋划先动手，却都停在半路，机会一点点被对方拿了过去。玄武门是入朝的必经之门，李世民在那里设伏，一击就把两个人一起解决。他中箭之后还爬进树林，几乎撞上李世民，可那时候做什么都晚了。他输在动手晚了半步。",
