    "a": "因为李渊身边最亲近的人是他。裴寂做着晋阳宫监，管的是炀帝的行宫，与镇守太原的李渊日日相见，说话不拘形迹；李世民若自己去劝，父子之间有些话反而说不出口，也容易被当作少年人的莽撞。所以他先拿私钱与裴寂赌博，每赌必输，把交情做到裴寂肯替他开口的地步。底本对这一段的记载很直白：钱是李世民的，输是有意的，为的就是让裴寂在要紧的时候替他说一句话。事情成了，首谋的名分自然落在裴寂头上。",
