    "a": "因为废掉的是名分，不是人。他做过太子、监过国，在宗室与旧臣里仍有分量；只要他活着，任何一次起兵都可以借他的名字。后来的事实就印证了这一点：李敬业起兵时，军中有人假冒章怀太子的名号。武则天派丘神勣去巴州，办的不是案子，是把这层可能彻底了结。她事后把丧事办得极体面，一面示人以爱子之情，一面把李贤已死的事实昭告天下，让拥护他的人死了翻盘的心。杀人之后还要用丧礼，这是同一件事的两面。",
