  "转折二：武德二年遣宋金刚南下，连陷太原、晋州，雀鼠谷大败唐援军，李元吉弃城而走，王行本响应，关中震恐。",
  "转折三：武德三年不纳苑君璋之谏而倾巢南下，李世民反击后宋金刚溃败，他弃并州北奔突厥，旋为突厥所杀。"
