MR.people["tang:p041"] = {
 "headline": "以六百人守睢阳十月，城破不屈",
 "lead": "张巡的籍贯家世，底本未详，只说他开元末年登进士第，天宝中期入仕，先任太子通事舍人，后出为清河县令，再调真源令；在任上扶危济困、选贤任能，颇有政绩。安禄山起兵后，他率众守雍丘，与叛将令狐潮反复争夺，城中矢尽粮绝，仍不肯降。叛将李庭望在雍丘城北筑城断他粮道，又连陷鲁郡、东平、济阴，遣杨朝宗进逼宁陵，他只好弃雍丘，转守宁陵，与睢阳互为声援。至德二载他退守睢阳，与许远分守城门，兵不满千，昼夜苦战，前后四百余战，杀伤叛军甚众；围城日久，粮尽援绝，城中罗雀掘鼠，终至以人为食，后世对此时有争议。睢阳陷落时，他被执不屈，与许远等同日遇害，年四十九，谥号与追赠底本未载。乱平之后，士论以忠烈称之，以一城之守牵制叛军，江淮转输赖以不绝。",
 "points": [
  "转折一：进士出身，由太子通事舍人出为清河县令、再调真源令，以扶危济困、选贤任能著称，是个十足的文官。",
  "转折二：安禄山反后率吏民起兵，据雍丘与叛军相持，粮道被断后弃雍丘转守宁陵，与睢阳互为声援。",
  "转折三：退守睢阳，以数百人分守四门，苦战十月，粮尽援绝而至以人为食，城破被执，骂不绝口而死。"
 ],
 "why": [
  {
   "q": "为什么一个文官县令，能把一座孤城守到十个月？",
   "a": "因为睢阳不是随便一座县城。它在汴河沿线，江淮的赋税由此北上，叛军要断唐廷的钱粮，非拔它不可；唐廷要保住江淮，也非守它不可。张巡手里虽然没有兵，却有治县多年攒下的信用，起兵时吏民肯跟着他走。守城时他与许远分守四门，在城头上和士卒同食共寝，几百人因此肯出死力。再加上城坚、粮尚可支，叛军顿兵坚城之下，一时也啃不动。他能守十个月，靠的是地利、人望与同甘苦三样，不是靠兵多。",
   "basis": {
    "type": "book",
    "text": "《大唐兴亡三百年》死守睢阳"
   }
  },
  {
   "q": "为什么他宁可让全城人饿死，也不肯弃城或投降？",
   "a": "因为在他眼里，睢阳一失，江淮就门户大开。底本写他以一城之守牵制叛军，江淮转输赖以不绝，这就是他死守的理由：城在，叛军的主力就被钉在这里；城弃，叛军南下，朝廷的钱粮就断了。他不是不知道城里已到了罗雀掘鼠的地步，也不是不知道援兵不会来，而是把这座城当成了必须付出的代价。也正因为这样，后世对他的评价才分成两半：一半敬他的忠，一半责他的忍。",
   "basis": {
    "type": "book",
    "text": "《大唐兴亡三百年》战火中的人间地狱"
   }
  }
 ],
 "gap": [
  "张巡的籍贯与家世，底本未详",
  "他登进士第的具体年份，史无明文",
  "睢阳被围期间城中人口的确切数目，底本未载",
  "他的谥号与追赠，书中未载"
 ],
 "quotes": []
};
