   "q": "为什么一个牢里的无赖，能被武后提拔成掌诏狱的侍御史？",
   "a": "因为武后当时最缺的正是这种人。她要改朝换代，宗室与朝臣里反对的人太多，走正常的司法程序办不成事，需要一批不问出身、只问效忠的人来办她的案子。来俊臣坐过牢，熟悉狱中的门道，又没有家世与清望可以依恃，除了依附她再无别的出路，用起来最放心。他自己也明白这一点，一见诏书就拼命喊冤告密，把命押在这条路上。一个敢下手、又没有退路的人，正好补上那个位置。",
