   "a": "因为她的权是从父亲的亏欠里长出来的。她生在贬谪路上，幼年随李显在房州辗转，那些年李显自身难保，妻女跟着受苦；一旦复位，这份亏欠就变成了纵容。中宗由着她开府置官、卖官鬻爵，宰相以下多出她门下，等于把用人的口子交了出去。她又与韦后、武三思结成一党，母亲在宫中，婆家在朝中，三处合起来，宫禁之内便没有人敢忤她的意。她的权势不是争来的，是被默许出来的。",
