 "headline": "一笔颜体，一副不肯弯的脊梁",
 "lead": "颜真卿是京兆万年人，祖籍琅琊，出自北齐颜之推一系，家学以训诂与书法传世。他开元年间中进士，历任监察御史、殿中侍御史，因为刚直被杨国忠所恶，出为平原太守。安禄山反时，河北郡县望风而降，他独守平原，与堂兄颜杲卿联兵讨贼，十七郡响应，替朝廷保全了江淮的转输之路。至德元载他撤离平原，渡黄河南下，又绕道荆州、襄阳北上，在次年四月抵达凤翔见到肃宗，此后历官宪部尚书、吏部尚书，封鲁郡公，以鲠直著称，论仆固怀恩之冤尤其切直。建中四年他奉诏宣慰李希烈，被扣留胁诱，始终不屈，兴元元年遇害，年七十六，谥文忠。他的书法初学张旭，后自成一格，笔力雄强，世称鲁公体，至今被奉为楷范。他的字与他的性子一样，都是一笔一笔撑住的，没有一处肯塌下来。",
