MR.people["tang:p048"] = {
 "headline": "屡试不第的盐商，走到长安称帝",
 "lead": "黄巢是曹州冤句人，家里以贩盐为业，颇有些资财。他善骑射，粗通书记，在乡里算得上是能文能武的人，可屡次应进士举都没能登第。乾符二年王仙芝起兵，他聚众响应，转战河南、淮南；王仙芝死后，众人推他做冲天大将军，率军渡江南下，经江西、浙东、福建，攻广州，再北上荆襄。广明元年他渡江北上，连下洛阳、潼关，十二月初进入长安，僖宗奔蜀，他称帝，国号大齐，改元金统。称帝之后大齐的号令出不了长安附近，诸镇仍在唐的名下，他又约束不住部众，长安粮尽，中和三年被迫东撤，围陈州将近一年，兵力疲敝。中和四年二月李克用渡黄河南下，他的军队一举溃散，他在泰山狼虎谷败死，年六十五，余部或降或散，大齐政权随之瓦解，唐室也名存实亡。",
 "points": [
  "转折一：屡应进士举不第，乾符二年王仙芝起兵便聚众响应，中原失利后渡江南下，被推为冲天大将军。",
  "转折二：广明元年渡江北上，连下洛阳、潼关，十二月入长安，僖宗奔蜀，他称帝建国，改元金统。",
  "转折三：约束不住部众，长安粮尽东撤，围陈州近一年而兵疲，中和四年在狼虎谷败死，大齐随之瓦解。"
 ],
 "why": [
  {
   "q": "为什么黄巢会从一个应举的书生走到起兵反唐？",
   "a": "因为正途对他关着门，而乱世给他开了另一扇。他家以贩盐为业，虽有资财，在当时的门第里仍算不上高门；他善骑射、粗通书记，屡次应进士举却始终不第，科举这条路走到头也没有结果。乾符二年王仙芝起兵，他聚众响应，从此不再等朝廷给名分，而是自己去拿。中原战事失利、部下数十人被招降之后，他选择渡江南下，说明他要的是队伍与活路，不是一个招安的官职。",
   "basis": {
    "type": "book",
    "text": "《大唐兴亡三百年》黄巢：被社会遗忘的人"
   }
  },
  {
   "q": "为什么他进了长安、称了帝，却守不住？",
   "a": "因为他有破城之力，没有立国之术。入长安之后他约束不住部众，长安的粮道一断，城中就撑不下去；中和三年被迫东撤，围陈州将近一年，把最后的兵力耗在城下。唐廷这边却把各镇的兵与沙陀的骑兵都调了过来，中和四年李克用渡黄河南下，他的军队一举溃散，尚让降了时溥，诸将降了朱全忠，身边只剩不足一千人。大齐的架子搭起来了，底下的仓廪、号令、人心一样没有。",
   "basis": {
    "type": "book",
    "text": "《大唐兴亡三百年》狼虎谷"
   }
  }
 ],
 "gap": [
  "黄巢屡试不第的具体次数与年份，底本未载",
  "他起兵时的最初部众数目，史无明文",
  "大齐政权的官制设置，书中未列",
  "他在狼虎谷的死状与葬处，底本未详"
 ],
 "quotes": []
};
