MR.people["tang:p049"] = {
 "headline": "弑君拥立，最终被自己荐的人毒死",
 "lead": "王守澄的籍贯家世，底本没有记载，宪宗朝他做内常侍，在禁中侍奉天子的日常起居。元和十五年正月宪宗暴崩，他与陈弘志等宦官一起动了手，随后拥立穆宗，从此掌权。穆宗、敬宗两朝他历任枢密使，势倾内外；敬宗遇弑之后，又由他迎立文宗。宪宗之死，朝野都知道是怎么回事，却没有人敢把话说出口，史家便把弑君之罪归在他名下。文宗不甘心受制于人，太和年间擢用李训、郑注，谋除宦官；李训等先把他外放削去兵权，再于太和九年遣人将他毒死，对外只说暴病。他死后不久甘露之变爆发，李训、郑注也败死，宦官势力反而更盛。他的卒年与谥号，底本未详；党羽多遭清算，而典兵之权已经转入仇士良之手，内廷从此又换了一个做主的人。",
 "points": [
  "转折一：宪宗朝做内常侍，元和十五年宪宗暴崩，他与陈弘志等动手，拥立穆宗，自此执掌内廷。",
  "转折二：穆宗、敬宗两朝历枢密使，敬宗遇弑后又迎立文宗，借天子患病独揽大权，郑注替他做代理人。",
  "转折三：文宗用李训、郑注除阉，先削其兵权，太和九年将他毒死，事称暴病；甘露之变后兵权归了仇士良。"
 ],
 "why": [
  {
   "q": "为什么一个内常侍能决定由谁做天子？",
   "a": "因为禁中的宿卫、诏令的出入、天子起居的消息都捏在内侍手里。元和十五年宪宗暴崩，事发在宫中，外朝无人预先知情，等到消息传出去，人选已经定了。吐突承璀虽有立澧王的主张，人却不在跟前；王守澄与陈弘志这些日常侍奉的内侍，反而是最方便下手、也最方便拥立的人。穆宗要坐稳御座，也乐得把这份拥立之功记在动手的人身上。一次宫中事变，就把一个内常侍变成了能换天子的人。",
   "basis": {
    "type": "book",
    "text": "《大唐兴亡三百年》宪宗之死"
   }
  },
  {
   "q": "为什么文宗要除掉他，最后却让宦官势力更大？",
   "a": "因为文宗手里没有兵，只能借人去办。他擢用李训、郑注，两人都是王守澄援引进来的，熟悉内廷的门路，又肯替天子下手；先以外任削去王守澄的兵权，再遣人下毒，对外说暴病。这一步办成了，可典兵之权没有回到天子手里，转入了仇士良之手。甘露之变一败，李训、郑注都死，宦官反而更盛。除掉一个人，没有除掉那套让宦官掌兵的规矩，这才是关键。",
   "basis": {
    "type": "book",
    "text": "《大唐兴亡三百年》甘露之变：喋血大明宫"
   }
  }
 ],
 "gap": [
  "王守澄的籍贯与家世，底本未载",
  "宪宗暴崩当夜宫中的具体情形，史无明文",
  "他任枢密使的起讫年月，底本未详",
  "他被毒死的具体日期与下毒之人，书中未载"
 ],
 "quotes": []
};
