    "q": "为什么王守澄敢对宪宗下手，还能拥立穆宗？",
    "a": "因为他占着最要紧的位置，也算准了没有人能追问他。内常侍日常侍奉天子起居，禁中宿卫与消息都从内廷走，事发在这一夜，外朝来不及反应。吐突承璀虽有立澧王的主张，人不在跟前，动手的先后就决定了一切。拥立穆宗之后，新天子需要有人替他背书，这份功劳正好由动手的人来领。宪宗之死朝野皆知，可追究这件事就等于质疑新天子的来路，于是谁都不开口。位置、时机、新天子的需要，三样凑齐，他才敢做。",
