MR.people["tang:p060"] = {
 "headline": "贬到西域的明经生，成了安西儒将",
 "lead": "裴行俭是河东裴氏绛州房人，父亲裴仁基是隋朝的将领。他在贞观年间以明经入仕，永徽年间经过六次升迁做到长安令，以干练著称于京畿。永徽六年，他因为反对高宗立武昭仪为皇后，被逐出长安，贬为西州都督府长史，从此投身西域。此后十年他悉心经营边事，熟悉边情，静待起用；麟德二年朝廷以他久历西陲、熟谙边务，擢为安西大都护，他在任经营安西四镇，抚绥诸部，西域渐安。调露元年他以计擒住西突厥可汗都支，不战而定西域，又大破突厥阿史那伏念，以功拜礼部尚书。他兼资文武，尤精草书，用兵重谋略而不专恃力，后世称他为儒将。永淳元年他奉命出击突厥，行至途中病卒，年六十四，谥献；儿子裴光庭后来也是开元名相，家风不坠。",
 "points": [
  "转折一：以明经入仕，永徽年间六迁至长安令；永徽六年因反对立武昭仪为后，被逐出长安，贬西州都督府长史。",
  "转折二：在边陲十年，熟谙边务，麟德二年擢安西大都护，经营四镇、抚绥诸部，西域渐安。",
  "转折三：调露元年计擒都支、破阿史那伏念，以功拜礼部尚书；永淳元年病卒征途，年六十四，谥献。"
 ],
 "why": [
  {
   "q": "为什么裴行俭反对立武昭仪为后，只是被贬而没有送命？",
   "a": "因为他的反对落在明处，罪名只是不合上意。永徽六年高宗要立武昭仪为皇后，朝中反对的人不止他一个，长孙集团的重臣正挡在前面；他只是长安令，位置不高，够不上首恶。把他逐出长安、贬到西州做都督府长史，既断了他在京畿的根基，又不至于闹出杀谏臣的名声。西州远在边陲，去那里等于政治上的绝路；可这条路他走成了活路，十年经营边事，反而攒下了别人没有的边功。",
   "basis": {
    "type": "book",
    "text": "《大唐兴亡三百年》向长孙集团宣战"
   }
  }
 ],
 "gap": [
  "裴行俭的生年，底本未标",
  "他父亲裴仁基的官职细节，书中未载",
  "他在西州十年的具体建树，底本未载",
  "他草书示人的具体情形，史无明文"
 ],
 "quotes": []
};
