    "a": "因为制诏这件事在武后临朝时成了最忙的活，而外朝的词臣并不都肯替她写。掖庭里的罪臣家眷是最好用的一类人：身家性命全在宫中，没有门生故吏，也没有地方上的根基，写得好就赏，写不好就罚，不必担心她反手结党。上官婉儿自幼熟读诗书，史传也读得广，文词与吏事两样都拿得起，才华是现成的；她祖父上官仪本就是高宗朝的宰相与名诗人，家学也没有断。武后赏识她，先让她掌诏命、参决表奏，一试十余年，位置就坐稳了。",
