MR.people["tang:p063"] = {
 "headline": "诗名满天下的明经生，相位坐不暖",
 "lead": "元稹字微之，河南洛阳人，为北魏宗室后裔，父元宽早卒，家道中落。他自幼丧父，家境贫寒，天性聪颖，勤奋好学，少有才名，贞元年间以明经登第，年纪轻轻便入了仕。元和元年他应制举对策第一，授左拾遗，与白居易倡和，诗名满天下，时号元白，所作号为元和体。他在左拾遗任上屡陈时政，触忤宦官与权臣，元和五年被贬为江陵府士曹参军，此后十年辗转通州、虢州，仕途偃蹇，诗文愈工。穆宗即位后他入为翰林学士，掌内外制诰，草诏敏速，参预机要，为穆宗所倚；长庆二年拜相，未几即为李逢吉所排，罢为同州刺史。此后他历越州刺史、武昌军节度使，在越州修水利、兴学校，颇有治绩；与白居易书札往还，唱和之作编为元白唱和集。大和五年他暴卒于任，年五十三。他的诗从士大夫到市井小民都在传，后来人记得的，多半是元和体而不是他的官。",
 "points": [
  "转折一：家道中落的明经生，元和元年制举对策第一授左拾遗，与白居易倡和，元和体传遍朝野。",
  "转折二：屡陈时政触忤宦官权臣，元和五年贬江陵士曹，此后十年辗转通州、虢州，诗文愈工。",
  "转折三：穆宗朝召入翰林、长庆二年拜相，未几为李逢吉所排罢为同州刺史，大和五年暴卒于任。"
 ],
 "why": [
  {
   "q": "为什么他能从家道中落走到制举第一、诗名满天下？",
   "a": "因为他走的是一条当时最正的路，又把这条路走成了自己的。他父亲元宽早卒，家道中落，明经登第是他能抓住的第一个台阶；元和元年宪宗新即位，要收人心，制举是朝廷向天下取士的正途，他对策第一，清望立刻就有了。诗名是另一条线：他与白居易倡和，两个人的诗从衣冠士子传到闾阎下俚，人人传诵，号为元和体、元白。文章与对策同出一手，他在朝中有话可说，在民间有诗可传，这两样加在一起，才撑得起他后来的仕途。",
   "basis": {
    "type": "book",
    "text": "《大唐兴亡三百年》元稹的仕途：官场就是一张网"
   }
  },
  {
   "q": "为什么他的相位坐得这么短？",
   "a": "因为他坐上去的时候，朝中的位置已经不够分了。长庆二年他拜相，同列有裴度，两人各有各的路数；李逢吉要的是相位，最省事的办法是让前面的人互相消耗。底本说穆宗用他只是权宜之计，可见天子并没有把他当成不可替换的人。他自己也不肯放弃对相位的角逐，一有风吹草动就想再争，反而给了对手口实。罢为同州刺史，表面像是被天子疏远，实则是李逢吉收拾局面的第一步。一个靠笔和口才上来的人，在宰相的位子上，缺的正是可以倚仗的党与兵。",
   "basis": {
    "type": "book",
    "text": "《大唐兴亡三百年》相权之争：渔翁得利的李逢吉"
   }
  }
 ],
 "gap": [
  "他明经登第的具体年份，底本未载",
  "他罢相为同州刺史的月日，史无明文",
  "他在越州所修水利的工程名目，书中未录",
  "他的谥号，底本未载"
 ],
 "quotes": []
};
