    "近端触发：贞元十年十一月他连续上疏，历数裴延龄的罪恶，痛斥其为奸诈小人，还把矛头直指德宗，说天子护着此人，连他的罪状也懒得问。",
    "决策者动机：他要的是把纲纪摆回朝堂，宁可犯上也要把话说清；德宗要的是钱与顺意的人，最不愿被臣下当面揭短。"
