    "a": "因为他把最不该说的话说到了天子脸上。贞元年间朝廷缺钱，裴延龄替德宗挪东补西、以羡余报功，德宗正用得着这样的人；陆贽做宰相，偏要论两税之弊、边储之策，话又重得让人抬不起头，天子的脸面常常挂不住。贞元十年十一月他连续上疏，把裴延龄的罪一条条数出来，还直指德宗护着此人、连罪状也不肯过问，这就不是议事，是当面揭短了。朝中嫉贤妒能的人再一编排，构陷就有人信。罢相贬忠州，是德宗护着裴延龄、也是护着自己。",
