   "a": "因为宗室领兵最怕两件事：一是仗着姓李不听调度，二是拿兵去争名。李道宗两样都不犯。他少年从军，跟着李世民打过四方，知道军中规矩；灵州都督任上镇抚突厥降部，边人安之，说明他会带人也懂得安置人。吐谷浑之役他与侯君集分道进击，功居其首，是能打；驻跸山敢率数十骑冲阵，又肯献直捣平壤之策，是有胆有识。太宗说他忠谨，忠是听命，谨是不越分。宗室之中能做到这两点的，不多。",
