    "a": "因为他是这一路的主将，副将失期也要记在主将账上。河口一战他先胜，随后郭待封放弃大非岭、擅自带辎重前进，被吐蕃二十万之众伏击，粮械尽失；前军无粮，胜负已定。军法不问是谁先犯错，只问这一路归谁节制。高宗念他以往的功勋，免了死罪，仍革职除名，这已是轻处。底本把这一战写成他一世英名的转折，原因也在这里：他半生靠阵前之勇立名，这一次败在调度与辎重。",
