   "a": "因为给官的人是武后，不是外朝。控鹤府是为近侍单设的机构，官职从宫中出，既不必经宰相拟授，也不占外朝的名额；他又是门荫出身，本来就有入仕的资格，缺的只是一个留在宫里的理由。美貌与音律正好补上这一条：侍宴承旨赋诗，武后为之解颐，日子久了，奉宸令与恒国公都是顺理成章的事。他的升迁不靠政绩，靠的是离武后有多近。",
