MR.people["tang:p084"] = {
 "headline": "跃马挺枪的勇将，身后成了门神",
 "lead": "秦琼字叔宝，齐州历城人，家世无考。他少年在隋将来护儿帐下，以勇悍得赏识；隋末先后隶属张须陀、裴仁基，后随裴仁基归瓦岗，隶于李密；李密败后为程知节所劝，一同归唐，入秦王府。李世民素闻其名，厚礼相待，任他为骑兵总管，又遴选最骁勇的骑兵千余人组成玄甲军；他每战跃马挺枪，出入敌阵，玄甲军之名由此震动。武德九年六月玄武门事起，他预其役；贞观年间历官左武卫大将军，封翼国公。他晚年多病，曾说少长戎马、前后出血数升，安得不病，闻者壮之。贞观十二年病卒，赠徐州都督，谥壮，陪葬昭陵，图形凌烟阁；后世图画其像与尉迟恭同贴门扉，遂为民间门神。一个从未留下兵书的人，倒把名字留在了千家万户的门上。",
 "points": [
  "转折一：隋末辗转于来护儿、张须陀、裴仁基帐下，随军归瓦岗，又随李密之败而归唐。",
  "转折二：入秦王府为骑兵总管，每战跃马挺枪出入敌阵，玄甲军之名由此震动。",
  "转折三：预玄武门之役，贞观朝官至左武卫大将军，卒谥壮，图形凌烟阁。"
 ],
 "why": [
  {
   "q": "为什么李世民一见秦琼就厚礼相待，任他为骑兵总管？",
   "a": "因为李世民要建的是一支能野战破阵的骑兵。隋末唐军与诸雄相接，胜负常在骑阵一冲之间；秦琼在来护儿、张须陀帐下就以勇悍知名，又亲身经历过瓦岗的骑战，是当时少数既敢冲阵、又能带骑兵的人。李世民素闻其名，不必试用就把骑兵交给他，是把玄甲军这一类精锐押在一个已经证明过的人身上。用降将而不疑，正是秦王府能聚人的原因。",
   "basis": {
    "type": "book",
    "text": "《大唐兴亡三百年》可怕的李世民，完美的李世民"
   }
  },
  {
   "q": "为什么一个降将能进秦王府核心，还预了玄武门之役？",
   "a": "因为秦王府的班底是在战场上打出来的，不是按门第排的。秦琼归唐即入秦王府，随李世民征战，功劳与信任一起积；到武德末年，秦王府与东宫势不两立，能动员的只有这一批旧部。他预其役，不是临时被拉进来，是十几年一直就在里面。也正因如此，贞观朝他官至左武卫大将军、封翼国公，卒后还能图形凌烟阁。",
   "basis": {
    "type": "book",
    "text": "《大唐兴亡三百年》被孤立的痛苦"
   }
  }
 ],
 "gap": [
  "秦琼的家世与先世，底本无考",
  "他在张须陀帐下的具体战功，书中未载",
  "玄武门之役中他所任的具体职守，史无明文",
  "他出血数升之语的原话，底本只存大意",
  "门神之俗起于何时，底本未载"
 ],
 "quotes": []
};
