    "a": "因为他守的是城，朱温围的是粮。天复元年朱温兵围凤翔，天复二年他出兵战于虢县北，大败，被杀一万余人，野战已经打不过；围久了城中粮尽，天子在他手里非但不是筹码，还是负担——城破则连人带名一起丢。杀韩全诲等宦官、与朱温议和、送出昭宗，是当时唯一能保住凤翔的办法。天子一交，他的势也就到头：天复三年昭宗东归，所辖州郡多被削夺。挟天子这一手他学得像，却没有朱温的兵。",
